code_example:
#include <iostream>
#include <cstdlib>
struct Point2w {
  int x, y;
  Point2w(int a, int b) : x(a), y(b) { std::cout << "Constructor called for (" << x << ", " << y << ")\n"; }
  ~Point2w() { std::cout << "Destructor called for (" << x << ", " << y << ")\n"; }
};
int main() {
  void* arena = malloc(sizeof(Point2w) * 2);
  Point2w *p2w = new (arena) Point2w(10, 20);
  p2w = new (arena + sizeof(Point2w)) Point2w(30, 40);
  ((Point2w*)arena)->~Point2w();
  ((Point2w*)(arena + sizeof(Point2w)))->~Point2w();
  free(arena);
  return 0;
}
